  const handleZoneClick = (zoneName: string) => {
    if (onRegionClick) {
      // Utiliser la fonction de callback fournie (pour le filtrage)
      onRegionClick(zoneName);
    } else {
      // Navigation vers la page de la zone (comportement par défaut)
      router.push(`/communaute/${zoneName}`);
    }
  };

